'use strict';

/*
 * 1.1.6 — RFC 8785 (JCS) canonicalization vectors (test/vectors/rfc8785.json, generated by
 * test/gen-rfc8785-vectors.js with this repository's canonicalizer). Every vector is checked here with
 * verify.js canonicalJson: the canonical string, and the sha256 of its UTF-8 bytes.
 */

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const crypto = require('node:crypto');
const path = require('node:path');

const { canonicalJson } = require('../verify.js');
const doc = require(path.join(__dirname, 'vectors', 'rfc8785.json'));

describe('RFC 8785 canonicalization vectors (verify.js canonicalJson)', () => {
  it('the file is well formed: unique ids, every input is JSON text', () => {
    assert.ok(Array.isArray(doc.vectors) && doc.vectors.length > 0);
    const ids = doc.vectors.map((v) => v.id);
    assert.equal(new Set(ids).size, ids.length, 'unique ids');
    for (const v of doc.vectors) {
      assert.equal(typeof v.input_json, 'string', v.id);
      JSON.parse(v.input_json);
      assert.match(v.sha256, /^[0-9a-f]{64}$/, v.id);
    }
  });

  for (const v of doc.vectors) {
    it(`${v.id} ${v.name}`, () => {
      const canonical = canonicalJson(JSON.parse(v.input_json));
      assert.equal(canonical, v.canonical);
      assert.equal(crypto.createHash('sha256').update(Buffer.from(canonical, 'utf8')).digest('hex'), v.sha256);
      assert.equal(/\s/.test(canonical.replace(/"(?:[^"\\]|\\.)*"/g, '')), false, 'no whitespace outside strings');
    });
  }

  it('the recorded cross-check with verify.py is consistent with the vectors it names', () => {
    const cc = doc.cross_check;
    assert.equal(cc.of, doc.vectors.length);
    assert.equal(cc.agrees + cc.differs.length, cc.of);
    for (const id of cc.differs) assert.ok(doc.vectors.some((v) => v.id === id), id);
  });
});
